Cascade Layers Intro:
@layer reset, base, components, utilities;

@layer reset {
    *, *::before, *::after {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }
}

@layer base {
    body { font-family: system-ui; line-height: 1.6; color: #333; }
    a { color: #4A90D9; text-decoration: none; }
}

@layer components {
    .card { border: 1px solid #ddd; padding: 1rem; border-radius: 8px; }
    .btn { padding: 0.5rem 1rem; border-radius: 6px; background: #4A90D9; color: white; }
}

@layer utilities {
    .mt-4 { margin-top: 1rem; }
    .text-center { text-align: center; }
}

